import puppeteer from 'puppeteer-core';

const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const BASE = 'http://localhost:5225';
const log = (...a) => console.log(...a);

const browser = await puppeteer.launch({
  executablePath: CHROME,
  headless: 'new',
  args: ['--no-sandbox'],
});
const page = await browser.newPage();
page.setDefaultTimeout(30000);

try {
  // 1. Login
  await page.goto(`${BASE}/Account/Login`, { waitUntil: 'networkidle2' });
  await page.type('input[name="Input.Email"]', 'admin@gatekeeper.local');
  await page.type('input[name="Input.Password"]', 'Admin!23456');
  await Promise.all([
    page.waitForNavigation({ waitUntil: 'networkidle2' }),
    page.click('button[type="submit"]'),
  ]);
  log('1. Logged in, url =', page.url());

  // 2. Go to Customers (interactive). Wait for the Blazor circuit to connect.
  await page.goto(`${BASE}/customers`, { waitUntil: 'networkidle2' });
  await page.waitForSelector('input.form-control');
  // Give the SignalR circuit a moment to establish so events are wired.
  await new Promise(r => setTimeout(r, 1500));

  const unique = 'Globex-' + Date.now();
  await page.type('input.form-control', unique);
  // Select Enterprise tier
  await page.select('select.form-select', 'Enterprise');
  await Promise.all([
    page.click('button[type="submit"]'),
    page.waitForFunction(
      (name) => document.body.innerText.includes(name) &&
                document.body.innerText.includes('Added customer'),
      {}, unique
    ),
  ]);
  log('2. Created customer via interactive circuit:', unique);

  // 3. Verify it persisted + shows in the table with Enterprise badge
  const inTable = await page.evaluate((name) => {
    const rows = [...document.querySelectorAll('tbody tr')];
    const row = rows.find(r => r.innerText.includes(name));
    return row ? row.innerText.replace(/\s+/g, ' ').trim() : null;
  }, unique);
  log('3. Row in customers table:', inTable);

  // 4. Verify an audit entry was written
  await page.goto(`${BASE}/audit`, { waitUntil: 'networkidle2' });
  await page.waitForSelector('tbody tr');
  const auditHit = await page.evaluate((name) => {
    const rows = [...document.querySelectorAll('tbody tr')];
    const row = rows.find(r => r.innerText.includes(name));
    return row ? row.innerText.replace(/\s+/g, ' ').trim() : null;
  }, unique);
  log('4. Audit entry:', auditHit);

  if (inTable && auditHit) {
    log('\nRESULT: PASS — interactive create persisted and was audited.');
  } else {
    log('\nRESULT: FAIL');
    process.exitCode = 1;
  }
} catch (e) {
  log('ERROR:', e.message);
  process.exitCode = 1;
} finally {
  await browser.close();
}

